import {PLAN,LABELS,addDays,daysBetween,weekday,monday,weekNumber,weekFor,phaseFor,moduleFor,minutes,timeStr,ukNow,dayPlan,progress,activeTasks,weeklySummary,deadlines,upcoming,findBuffer,automationTasks,validDate,validTime,overlap} from './engine.js';
import {weekProgress,milestoneIsActionable,completionStats,pendingCheckpoints,earlierMilestones,nextProjectSession,logUnfinished,resolveCheckpoint,finishSession} from './progress.js';
import {freshState,loadState,saveState,completeTask,deferTask,moveTask,backup,parseBackup,mergeStates,KEY} from './storage.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ICONS={today:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2m3 11 3 3 5-5',week:'M4 3h16v18H4zM8 8h8m-8 4h8m-8 4h5',roadmap:'M5 21V3m0 1h14l-3 4 3 4H5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m-2-5h4l1 3 3-1 2 3-2 3 2 3-2 3-3-1-1 3h-4l-1-3-3 1-2-3 2-3-2-3 2-3 3 1z',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',chevron:'m6 9 6 6 6-6',plus:'M12 5v14m-7-7h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',moon:'M20.5 14A9 9 0 0 1 10 3.5 9 9 0 1 0 20.5 14',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v5l3 2',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0m-7-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',coffee:'M4 8h12v7a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5zm12 0h2a3 3 0 0 1 0 6h-2M7 2v3m5-3v3',leaf:'M20 3C9 2 2 9 5 16c7 3 14-4 15-13M4 21 15 10',arrow:'M5 12h14m-5-5 5 5-5 5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',book:'M3 5c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2zm9 2v15',edit:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14z'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name]||ICONS.clock}"/></svg>`;
const btn=(text,action,cls='quiet',extra='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const textBtn=(text,action,extra='')=>`<button type="button" class="text-button" data-action="${action}" ${extra}>${text}</button>`;
const short=d=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const long=d=>new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const dayName=d=>new Intl.DateTimeFormat('en-GB',{weekday:'short',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const humanTime=t=>t==='23:59'?'onwards':t;
const color=k=>['reach','fyp','ucl'].includes(k)?'var(--accent)':['ai','cog','cogroup','quant'].includes(k)?'var(--violet)':['db','db2','cloud','cloud_exam','ai_exam'].includes(k)?'var(--blue)':'var(--amber)';
const badge=(s,warm=false)=>`<span class="badge ${warm?'warm':''}">${esc(s)}</span>`;
let state,loadWarning='';try{const x=loadState();state=x.state;loadWarning=x.warning;}catch{state=freshState();loadWarning='Device storage is unavailable. Changes will not survive closing; export a backup and allow site storage.';}
let route='today',selectedDate=ukNow().date,followingToday=true,taskMap=new Map(),pendingImport=null,installPrompt=null,registration=null,toastTimer=0,lastMinute='',progressCache=null;
function save(){try{saveState(state);$('#storage-status').textContent='Saved on this device';return true;}catch{const el=$('#storage-error');el.textContent='Your latest changes could not be saved on this device. Export a backup now, then check browser storage space and site permissions.';el.hidden=false;$('#storage-status').textContent='Changes need a backup';return false;}}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}
function setRoute(view,date=selectedDate){const h='#'+view+'?date='+date;if(location.hash===h){readRoute();render();}else location.hash=h;}
function readRoute(){const [tab,q]=location.hash.slice(1).split('?');route=['today','week','roadmap','settings'].includes(tab)?tab:'today';const d=new URLSearchParams(q).get('date');if(validDate(d))selectedDate=d;followingToday=selectedDate===ukNow().date;}
function applyTheme(){let theme=state.preferences.theme;if(theme==='system')theme=matchMedia('(prefers-color-scheme: light)').matches?'light':'dark';document.documentElement.dataset.theme=theme;$('#theme-toggle').innerHTML=icon(theme==='dark'?'sun':'moon');$('#theme-toggle').setAttribute('aria-label',theme==='dark'?'Use light theme':'Use dark theme');$('meta[name=theme-color]').content=theme==='dark'?'#10191e':'#f6f7f3';}
function field(label,name,type,value='',extra=''){return `<label class="field-label" for="${name}">${label}</label><input class="field" id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;}
const area=(label,name,value='',extra='')=>`<label class="field-label" for="${name}">${label}</label><textarea class="field" id="${name}" name="${name}" ${extra}>${esc(value)}</textarea>`;
function select(label,name,items,value){return `<label class="field-label" for="${name}">${label}</label><select class="field" id="${name}" name="${name}">${items.map(([v,l])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>`;}
function checkLabel(label,name,checked=false){return `<label class="check-label"><input type="checkbox" name="${name}" id="${name}" ${checked?'checked':''}><span>${label}</span></label>`;}
function formError(){return '<div id="dialog-error" role="alert"></div>';}
function formButtons(label='Save changes'){return `<div class="form-actions"><button class="button" type="submit">${label}</button>${btn('Cancel','close')}</div>`;}
function modal(title,body,eyebrow='YOUR PLAN'){const d=$('#modal');$('#dialog-content').innerHTML=`<div class="dialog-content"><div class="dialog-header"><div><p class="eyebrow">${eyebrow}</p><h2 id="dialog-title">${title}</h2></div><button type="button" class="icon-button unbordered" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}</div>`;if(!d.open)d.showModal();d.scrollTop=0;}
function closeModal(){if($('#modal').open)$('#modal').close();}
function heading(eyebrow,title,sub,controls=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div>${controls}</div>`;}
function dateControls(step=1){return `<div class="date-controls"><button class="icon-button" data-action="prev-date" data-step="${step}" aria-label="Previous ${step===7?'week':'day'}">${icon('left')}</button><input aria-label="Choose date" id="date-picker" type="date" value="${selectedDate}"><button class="icon-button" data-action="next-date" data-step="${step}" aria-label="Next ${step===7?'week':'day'}">${icon('right')}</button></div>`;}
function dayStrip(){const start=monday(selectedDate);return `<div class="day-strip" aria-label="Days of this week">${Array.from({length:7},(_,i)=>{const d=addDays(start,i);return `<button class="day-button ${d===selectedDate?'selected':''} ${d===ukNow().date?'today':''}" data-action="date" data-date="${d}" aria-label="${long(d)}" ${d===selectedDate?'aria-current="date"':''}><span>${dayName(d)}</span><strong>${Number(d.slice(-2))}</strong></button>`;}).join('')}</div>`;}
function ring(p){return `<div class="ring" style="--p:${p.percent}" role="progressbar" aria-label="Required work complete" aria-valuenow="${p.percent}" aria-valuemin="0" aria-valuemax="100"><div class="ring-inner">${p.percent}%<small>${p.done} OF ${p.total} DONE</small></div></div>`;}
function check(id,done,context='task',label='Complete session'){return `<button class="check" data-action="check-${context}" data-id="${esc(id)}" aria-pressed="${done}" aria-label="${esc(done?'Undo: '+label:label)}">${icon('check')}</button>`;}
function taskCard(t,current){taskMap.set(t.id,t);const done=state.records[t.id]?.status==='done',isLife=!t.actionable&&!['buffer'].includes(t.subject),live=current?.id===t.id;return `<article class="activity ${done?'done':''} ${isLife?'lifestyle':''} ${live?'current':''}" style="--category:${color(t.subject)}" data-task="${esc(t.id)}"><div class="time-rail"><time>${t.start}</time><span class="end">${humanTime(t.end)}</span></div><div class="activity-body">${live?'<span class="now-badge">NOW</span>':''}<div class="activity-row">${isLife?`<div class="life-content">${icon(t.subject==='free'?'moon':t.title.includes('Lunch')||t.title.includes('breakfast')?'coffee':'leaf','life-icon')}<div><span class="activity-title">${esc(t.title)}</span><span class="activity-mini">${esc(t.detail)}</span></div></div>`:`<button class="activity-open" data-action="task" data-id="${esc(t.id)}"><span class="category">${esc(LABELS[t.subject]||t.subject)} ${t.optional?badge('Optional'):''} ${t.blocked?badge('Approval needed',true):''}</span><span class="activity-title">${esc(t.title)}</span><span class="activity-mini">${icon('pin')}${esc(t.location||'Home')}${t.continuation?' · Continuing unfinished work':t.reallocated?' · Reallocated':''}${t.window?' · Window '+esc(t.window):''}</span></button>${t.actionable?check(t.id,done,'task',t.title):''}`}</div></div></article>`;}
function deadlineItems(ds){return ds.map(d=>`<button class="deadline-item" data-action="deadline" data-id="${esc(d.id)}"><div class="deadline-date"><span>${d.date?short(d.date)+(d.time?' · '+d.time:' · time TBC'):esc(d.window||'Date to confirm')}</span>${d.complete?badge('Complete'):d.status!=='confirmed'?badge('TBC',true):''}</div><div class="deadline-title">${esc(d.title)}</div><div class="deadline-count">${d.date?countdown(d.date,selectedDate):'Enter the allocated date when it is published'}</div></button>`).join('');}
function countdown(date,from){const n=daysBetween(date,from);return n===0?'Due today':n===1?'Tomorrow':n>0?n+' days away':Math.abs(n)+' days ago · check status';}
function planProgress(){return progressCache||(progressCache=completionStats(state));}
function weeklyProgressPanel(start,compact=false){const p=weekProgress(start,state),record=planProgress();if(!p.number)return '';return `<section class="weekly-progress ${compact?'compact':''}"><div class="row-between"><h2>Week ${p.number} <span class="subtle">· ${p.percent===100?'complete':'your progress'}</span></h2><strong>${p.percent}%</strong></div><div class="progress-bar weekly-bar" role="progressbar" aria-label="Week ${p.number} combined progress" aria-valuenow="${p.percent}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${p.percent}%"></div></div><div class="week-progress-breakdown"><span>Daily sessions <b>${p.sessionsDone}/${p.sessionsTotal}</b></span><span>Milestones <b>${p.milestoneDone}/${p.milestoneTotal}</b></span>${p.followupTotal?`<span>Checkpoints <b>${p.followupDone}/${p.followupTotal}</b></span>`:''}</div><div class="row-between week-progress-foot"><span><strong>${record.complete}</strong> of ${record.total} weeks reached 100%</span>${textBtn(compact?'Open week '+icon('arrow'):'View all weeks '+icon('arrow'),compact?'week':'nav',compact?'':'data-view="roadmap"')}</div>${compact?'':'<p class="subtitle">100% means the required sessions, weekly milestones and recorded unfinished checkpoints are complete. Moving or deferring a session keeps it outstanding in its original week.</p>'}</section>`;}
function checkpointList(date){const cps=pendingCheckpoints(state,date),queued=(state.queuedGoals||[]).filter(g=>g.status==='waiting');if(!cps.length&&!queued.length)return '';return `<section class="checkpoint-panel"><div class="section-head"><h2>Pick up where you left off</h2><span class="caption">${cps.length} open</span></div>${cps.map(c=>`<div class="checkpoint-item"><div class="category" style="--category:${color(c.subject)}">${esc(LABELS[c.subject]||'Coursework')}</div><h3>${esc(c.title)}</h3><p>${esc(c.nextAction)}</p><div class="checkpoint-meta">${c.remainingMinutes} minutes estimated · belongs to ${short(c.originDate)}${c.autoContinue?' · continues in future module blocks':''}</div><div class="form-actions">${btn('Checkpoint finished','resolve-checkpoint','quiet small',`data-id="${esc(c.id)}"`)}${btn('Update next step','edit-checkpoint','quiet small',`data-id="${esc(c.id)}"`)}${!c.autoContinue?btn('Continue in module blocks','enable-checkpoint','quiet small',`data-id="${esc(c.id)}"`):''}</div></div>`).join('')}${queued.length?`<details class="settings-detail"><summary>${queued.length} originally planned objective(s) retained in the queue</summary><ul>${queued.map(g=>`<li>${esc(g.task.title)}</li>`).join('')}</ul></details>`:''}<p class="subtitle">Submission checks and fixed appointments stay protected. If the remaining work needs more time than your available blocks, use Friday’s review to change the scope or allocation.</p></section>`;}
function weekRecord(){const stats=planProgress();return `<section class="panel week-record"><div class="row-between"><div><p class="eyebrow">PROGRESS ACROSS THE YEAR</p><h2>${stats.complete} of ${stats.total} weeks at 100%</h2></div><span class="week-record-mark">${stats.complete}</span></div><p>Every week has its own record. There is no streak to protect; you can return to unfinished work and update a week later.</p><div class="week-record-grid">${stats.weeks.map(w=>`<button class="week-record-cell ${w.progress.complete?'complete':''} ${w.start===monday(selectedDate)?'selected':''}" data-action="open-week" data-date="${w.start}" aria-label="Week ${w.number}: ${w.progress.percent}% complete"><span>W${w.number}</span><strong>${w.progress.complete?icon('check'):w.progress.percent+'%'}</strong></button>`).join('')}</div></section>`;}
function milestoneList(w){return `<div class="milestones">${w.outcomes.map((m,i)=>{if(!milestoneIsActionable(m))return '';const id=`w${w.number}/m${i}`;return `<div class="milestone ${state.milestones[id]?'checked':''}">${check(id,!!state.milestones[id],'milestone',m)}<label data-action="check-milestone" data-id="${id}">${esc(m)}</label></div>`;}).join('')}</div>`;}
function backlog(date){let rows=[];const start=date>PLAN.end?addDays(PLAN.end,-14):addDays(date,-14);for(let i=0;i<14;i++){const d=addDays(start,i);if(d<PLAN.start||d>=date)continue;const p=dayPlan(d,state);rows.push(...p.conflicts.filter(t=>state.records[t.id]?.status!=='done'));for(const t of p.tasks){if(!t.actionable||t.optional||state.records[t.id]?.status==='done'||t.subject==='review')continue;if(t.date==='2026-11-07'||state.records[t.id]||state.notes[t.id])rows.push({...t,conflictReason:'Still available from '+short(t.date)+'. Review whether it is still useful.'});}}return [...new Map(rows.map(t=>[t.id,t])).values()];}
function conflictList(items){return items.map(t=>{taskMap.set(t.id,t);return `<div class="conflict-card"><strong>${esc(t.title)}</strong><p>${esc(t.conflictReason||t.conflictWith)}${t.conflictWith?' '+esc(t.conflictWith):''}</p><div class="conflict-actions">${textBtn('Choose a time','task',`data-id="${esc(t.id)}"`)}${textBtn('Find a buffer','buffer',`data-id="${esc(t.id)}"`)}</div></div>`;}).join('');}
function todayView(){const p=dayPlan(selectedDate,state),prog=progress(p.tasks,state),a=activeTasks(p),isToday=selectedDate===ukNow().date,w=p.week?weekFor(selectedDate):null;
const focus=a.current?.actionable?a.current:a.next?.actionable?a.next:p.tasks.find(t=>t.actionable&&state.records[t.id]?.status!=='done');
const title=p.week?'Your day, with clarity.':selectedDate>PLAN.end?'A little room for what’s next.':selectedDate<PLAN.start?'Make this day your own.':'A good place to begin.';
const context=p.week?`Week ${p.week} of 34 · ${p.phase.name}`:selectedDate<PLAN.weekStart&&selectedDate>=PLAN.start?'Before Week 1 · a gentle start':'Outside the academic plan · personal sessions still work';
let ds=upcoming(state,selectedDate,3);let missing=deadlines(state).filter(d=>!d.date&&!d.complete);
let past=backlog(selectedDate),allConflict=[...p.conflicts,...past].filter((t,i,a)=>a.findIndex(x=>x.id===t.id)===i);
return heading(isToday?'TODAY · '+long(selectedDate).toUpperCase():long(selectedDate).toUpperCase(),title,esc(context),dateControls())+dayStrip()+`<section class="focus-panel"><div><p class="eyebrow">${a.current?'RIGHT NOW':focus?'YOUR NEXT FOCUS':prog.total&&prog.done===prog.total?'DAY COMPLETE':'ROOM TO BREATHE'}</p><h2>${esc(a.current?.title||focus?.title||'Your time is yours.')}</h2><p>${a.current?`Next: ${esc(a.next?.title||'A free evening')} ${a.next?'· '+a.next.start:''}`:focus?`${focus.start}–${focus.end} · ${esc(LABELS[focus.subject]||'Personal task')}`:'Rest, see people and enjoy the space. Add a session only if you want one.'}</p><div class="focus-meta"><span>${icon('clock')}${prog.total} planned work sessions</span><span>${icon('moon')}Evenings protected</span></div></div>${ring(prog)}</section><div class="main-grid"><section><div class="section-head"><h2>${isToday?'Today’s rhythm':'The day’s rhythm'}</h2>${textBtn(icon('plus')+' Add session','new-event')}</div>${checkpointList(selectedDate)}<div class="timeline">${p.tasks.map(t=>taskCard(t,a.current)).join('')||'<div class="empty-state"><h3>A clear page.</h3>This date sits outside the November–July academic plan. Your appointments and personal sessions still appear here.</div>'}</div>${weeklyProgressPanel(monday(selectedDate),true)}${allConflict.length?`<details class="settings-detail" ${p.conflicts.length?'open':''}><summary>${allConflict.length} session${allConflict.length===1?'':'s'} to review · choose the next time</summary><p class="subtitle">Nothing moves automatically. Keep what matters and defer the rest.</p>${conflictList(allConflict)}</details>`:''}<details class="settings-detail"><summary>Notes for ${short(selectedDate)}</summary><form data-form="day-note">${area('A thought, a blocker or tomorrow’s first step','day-note',state.notes[selectedDate]||'','maxlength="12000"')}<div class="form-actions"><button class="button small" type="submit">Save note</button></div></form></details></section><aside class="right-rail"><section class="aside-card"><div class="section-head"><h2>Coming into view</h2>${icon('today')}</div>${deadlineItems(ds)||'<p class="subtitle">No confirmed future deadlines.</p>'}${textBtn('All dates + assessments '+icon('arrow'),'deadlines')}</section><section class="aside-card"><h2>Aim for this week</h2>${w?`<p class="subtitle">${esc(w.label)}</p>${milestoneList({...w,outcomes:w.outcomes.slice(0,3)})}${textBtn('The full week '+icon('arrow'),'week')}`:'<p class="subtitle">Sort the urgent admin, prepare for the Cloud formative, and keep most of the weekend free.</p>'}</section><section class="quiet-card"><h3>${missing.length} dates still to confirm</h3><p>Exams, vivas and personal application dates stay provisional until you enter the real details.</p><p class="signature">Good work. Room to live.</p><p>Only required work counts towards your day. Walks, meals and optional extras are simply part of life.</p></section></aside></div>`;}
function weekView(){const start=monday(selectedDate),n=weekNumber(start),w=n?PLAN.weeks[n-1]:null,sum=weeklySummary(start,state),combined=weekProgress(start,state),hours=Object.entries(sum.hours).sort((a,b)=>b[1]-a[1]);return heading('A WEEK AT A TIME',w?'Week '+n+' · '+w.label:'Your week',short(start)+' — '+short(addDays(start,6))+' · '+(phaseFor(start)?.name||'Personal planning'),dateControls(7))+`<section class="focus-panel"><div><p class="eyebrow">MEANINGFUL WORK, THEN SWITCH OFF</p><h2>${combined.percent}% of this week complete.</h2><p>${w?esc(w.outcomes[0]):'Add appointments or personal work to shape this week.'}</p><div class="focus-meta"><span>Daily work and coursework outcomes count together.</span></div></div>${ring(combined)}</section>${weeklyProgressPanel(start)}<div class="main-grid"><section><div class="section-head"><h2>Monday to Sunday</h2>${textBtn(icon('plus')+' Add appointment','new-event')}</div>${checkpointList(selectedDate)}<div class="week-list">${Array.from({length:7},(_,i)=>{const date=addDays(start,i),p=dayPlan(date,state),work=p.tasks.filter(t=>t.actionable||t.subject==='buffer');return `<article class="week-day"><div class="week-day-label"><strong>${dayName(date)}</strong><span>${short(date)}</span><button data-action="date" data-date="${date}">Open day</button></div><div>${work.map(t=>{taskMap.set(t.id,t);return `<div class="week-session ${state.records[t.id]?.status==='done'?'done':''}" style="--category:${color(t.subject)}"><time>${t.start}–${t.end}</time><button data-action="task" data-id="${esc(t.id)}">${esc(LABELS[t.subject]||'Personal')} · ${esc(t.title)} ${t.optional?'(optional)':''}</button></div>`;}).join('')||`<p class="weekend-note">${i===5?'Groceries, errands and room for people.':'A relaxed day with room to live.'}</p>`}${p.conflicts.length?`<p class="target-date">${p.conflicts.length} unscheduled session(s) · open the day to review.</p>`:''}</div></article>`;}).join('')}</div><details class="settings-detail" open><summary>Milestones · ${w?w.outcomes.filter((title,i)=>milestoneIsActionable(title)&&state.milestones[`w${n}/m${i}`]).length:0} complete</summary>${w?milestoneList(w):'<p class="subtitle">This week is outside the academic baseline.</p>'}</details>${progressTrackers()}</section><aside class="right-rail"><section class="aside-card"><h2>Your planned time</h2>${hours.map(([k,h])=>`<div class="allocation" style="--category:${color(k)}"><span><i class="allocation-dot"></i>${esc(LABELS[k]||k)}</span><span>${Number(h.toFixed(1))}h</span></div>`).join('')}<hr class="rule"><p class="subtitle">Ordinary target: FYP ~6h · SchoolReach ~4h · quant ~2h. Deadline weeks deliberately shift the balance.</p></section><section class="aside-card"><h2>On the horizon</h2>${deadlineItems(upcoming(state,start,4))}</section></aside></div>`;}
function progressTrackers(){const b=state.business;return `<details class="settings-detail"><summary>SchoolReach · commercial progress</summary><p class="subtitle">Manual cumulative figures. Leave unavailable metrics blank. £79.99 per customer/month; enter actual MRR yourself.</p><form data-form="business"><div class="metric-grid">${[['contacted','Prospects contacted'],['followups','Follow-ups'],['responses','Responses'],['trials','Trials started'],['customers','Paying customers'],['mrr','Actual MRR (£)']].map(([k,l])=>`<div class="metric"><label for="metric-${k}">${l}</label><input id="metric-${k}" name="${k}" type="number" min="0" ${k==='mrr'?'step="0.01"':'step="1"'} value="${esc(b[k])}" aria-label="${l}"></div>`).join('')}</div><div class="form-actions"><button class="button small">Save figures</button></div></form></details><details class="settings-detail"><summary>Quant · practice and mistakes</summary><p class="subtitle">Specific practice, an honest score and one useful lesson.</p><form data-form="quant">${field('Topic practised','quant-topic','text','','required maxlength="200" placeholder="Bayes · conditional probability"')}<div class="form-row">${field('Problems attempted','attempted','number','8','required min="0" max="1000"')}${field('Problems solved','solved','number','0','required min="0" max="1000"')}</div><div class="form-row">${field('Practice date','practice-date','date',selectedDate,'required')}${field('Timed practice (minutes)','timed','number','0','min="0" max="480"')}</div>${area('Mistake worth revisiting','mistake','','maxlength="3000"')}<div class="form-actions"><button class="button small">Log practice</button></div></form>${state.quantLog.slice().reverse().slice(0,10).map(q=>`<div class="log-row"><strong>${esc(q.topic)}</strong> · ${q.solved}/${q.attempted}<small>${short(q.date)} · ${q.timed||0} timed minutes</small>${esc(q.mistake||'')}</div>`).join('')}</details><details class="settings-detail"><summary>AI · 12 short lab-task uploads</summary><p class="subtitle">Teaching-week topics are provisional. Confirm the actual sheet and filename. Check after uploading your own ≤200-word Word/PDF file.</p><div class="status-list">${PLAN.labTasks.map(t=>`<div class="status-row"><input id="${t.id}" type="checkbox" data-lab="${t.id}" ${state.labTasks[t.id]?'checked':''}><label for="${t.id}">Teaching week ${t.teachingWeek} · ${esc(t.topic)}</label></div>`).join('')}</div></details>`;}
function roadmapView(){const n=weekNumber(selectedDate);return heading('THE LONG VIEW','A year with direction.','34 weeks · 9 November 2026 — 4 July 2027. Start with the week in front of you.')+weekRecord()+`<div class="notice green">Academic requirements come from your supplied NTU assessment plan. Timetables adapt after you mark assessments, UCL or exams complete. Unknown dates stay unconfirmed.</div><div class="roadmap-list">${PLAN.phases.map(p=>`<details class="phase ${n>=p.first&&n<=p.last?'current':''}" ${n>=p.first&&n<=p.last?'open':''}><summary><div class="phase-week">WEEK${p.first===p.last?'':'S'} ${p.first}${p.first===p.last?'':'–'+p.last}</div><div><div class="phase-title">${esc(p.name)}</div><div class="phase-copy">${esc(p.summary)}</div></div><span class="phase-arrow">${icon('chevron')}</span></summary><div class="phase-body">${PLAN.weeks.filter(w=>w.number>=p.first&&w.number<=p.last).map(w=>`<div class="road-week"><div class="road-week-header"><div><h3>Week ${w.number} · ${esc(w.label)}</h3><p>${short(w.start)} — ${short(addDays(w.start,6))}</p></div>${textBtn('Open week '+icon('arrow'),'open-week',`data-date="${w.start}"`)}</div><ul>${w.outcomes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`).join('')}</div></details>`).join('')}</div><section class="panel module-guide"><h2>Module requirements, in one place</h2><p>The planner organises your work. Follow each assessment’s own rules when producing it.</p>${Object.entries(PLAN.modules).map(([k,m])=>`<details class="module-guide"><summary>${esc(m.name)} · ${m.code}</summary><div class="guide-content"><div class="notice">${esc(m.rule)}</div><ul>${m.requirements.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><a class="muted-link" href="${m.link}" target="_blank" rel="noopener noreferrer">Open the official NOW brief ↗</a></div></details>`).join('')}</section>`;}
function settingsView(){const prefs=state.preferences,auto=state.automation,ucl=state.uclSubmittedAt;return heading('MAKE IT YOURS','A plan that bends with life.','Keep the useful defaults. Adjust the details when life changes.')+`<div class="settings-grid"><section class="panel"><h2>Dates + assessments</h2><p>Published dates and allocated sessions live here. Add confirmed exam times to create real appointments; no exam sitting is invented.</p>${deadlineItems(deadlines(state).filter(d=>!d.complete).slice(0,4))}${textBtn('Manage all dates '+icon('arrow'),'deadlines')}<details class="settings-detail"><summary>${deadlines(state).filter(d=>d.complete).length} assessments marked complete</summary>${deadlineItems(deadlines(state).filter(d=>d.complete))}</details></section><section class="panel"><h2>Your device, your progress.</h2><p>Progress and notes save on this device. There is no automatic sync. Clearing site/app storage can erase them; keep a JSON backup before changing devices or addresses.</p><div class="form-actions">${btn(icon('download')+' Export JSON','export','')}${btn(icon('upload')+' Restore / merge','import')}</div><p class="subtitle">${state.lastBackup?'Last export: '+esc(state.lastBackup.slice(0,10)):'No export recorded yet.'}</p><details class="settings-detail"><summary>Install + use offline</summary><p>After deploying to HTTPS, open the site in Android Chrome, let it finish loading, then use ⋮ → Install app or Add to Home screen. Open once online, then try airplane mode.</p>${btn('Install My Plan','install','quiet small',installPrompt?'':'disabled')}<p id="offline-detail">Checking offline availability…</p><p>Updates offer an “Update now” button. They replace app files while keeping local progress. No background push reminders are promised.</p>${textBtn('Check for an app update','check-update')}${textBtn('Request durable device storage','persist-storage')}</details><details class="settings-detail"><summary>Legacy / recovery information</summary><p>Version 3 backups can be imported where dates/subjects match. Unmatched entries remain in your backup for manual review; old positional milestone checks are not guessed.</p><p>${state.legacyUnmapped.length} retained legacy records.</p>${textBtn('Download raw saved data','export-raw')}</details></section>
<section class="panel"><h2>UCL · early, and ready.</h2><p>Internal target: <strong>${short(state.uclTarget)}</strong>, editable below. This is your own target, not an official deadline. Submit as soon as the window is open and the application is strong.</p><a class="muted-link" href="https://www.ucl.ac.uk/study/prospective-students/graduate/courses/computational-finance-msc" target="_blank" rel="noopener noreferrer">Check official course dates ↗</a><div class="notice">No official opening/closing date is confirmed here. Check the 2027 entry page and admissions availability; funding has separate deadlines. Two academic references are required.</div><div class="status-list">${PLAN.uclSteps.map((s,i)=>`<div class="status-row"><input id="ucl-step-${i}" type="checkbox" data-ucl="${i}" ${state.uclChecklist[i]?'checked':''}><label for="ucl-step-${i}">${esc(s)}</label></div>`).join('')}</div><form data-form="ucl"><div class="form-row">${field('Internal target date','ucl-target','date',state.uclTarget,'required')}${field('Submitted on (leave blank until done)','ucl-submitted','date',ucl)}</div><div class="form-actions"><button class="button small">Save UCL status</button></div></form>${ucl?'<div class="notice green">Submitted. Future UCL blocks split between SchoolReach and quant; completed history stays intact.</div>':''}</section>
<section class="panel"><h2>FYP · approval before practice.</h2><p>Ethics was submitted, but approval has not been verified here. Until you record supervisor approval on DCS, FYP sessions show permitted research planning and keep practical milestones visible as pending.</p><form data-form="ethics">${checkLabel('I have verified supervisor ethics approval on DCS','ethics-approved',state.ethics.approved)}${field('Approval verified on','ethics-date','date',state.ethics.date||ukNow().date,'required')}${field('Approval reference / note (optional)','ethics-reference','text',state.ethics.reference,'maxlength="500"')}<div class="form-actions"><button class="button small">Save approval status</button></div></form><a class="text-button" href="https://dcs.ntu.ac.uk" target="_blank" rel="noopener noreferrer">Open DCS ↗</a></section>
<section class="panel span-2"><div class="row-between"><div><h2>Appointments + personal sessions</h2><p>Lessons, meetings, required attendance or an optional evening session. Fixed appointments move overlapping work to the visible unscheduled list.</p></div>${btn(icon('plus')+' Add','new-event','quiet small')}</div>${state.events.length?state.events.slice().sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start)).map(e=>`<div class="calendar-entry"><div>${esc(e.title)}${e.optional?' · optional':''}<small>${short(e.date)} · ${e.start}–${e.end} · ${esc(e.location||'Your choice')}</small></div>${textBtn('Edit','edit-event',`data-id="${esc(e.id)}"`)}</div>`).join(''):'<p class="subtitle">No custom appointments yet. Home is the default work location.</p>'}</section>
<section class="panel"><h2>Brother’s automation</h2><p>A short, optional setup sprint once agreed. No recurring Friday work and no assumed income.</p><form data-form="automation">${checkLabel('Agreement confirmed','auto-agreed',auto.confirmed)}${checkLabel('Sample documents and workflow received','auto-documents',auto.documents)}<div class="form-row">${field('Sprint starts (weekend suggested)','auto-start','date',auto.start||nextSaturday(),'required')}${field('Estimated focused hours','auto-hours','number',auto.hours||10,'min="2" max="40" step="0.5" required')}</div>${auto.activatedAt?'<p class="subtitle">Sprint activated. Changing the estimate records the new scope; edit the individual stages below to change their actual dates or duration.</p>':''}<div class="form-actions"><button class="button small" type="submit">${auto.activatedAt?'Save sprint details':'Activate optional sprint'}</button></div></form>${auto.tasks.map(t=>{taskMap.set(t.id,{...t,subject:'auto',category:'admin',actionable:true});return `<div class="sprint-stage">${check(t.id,state.records[t.id]?.status==='done','task',t.title)}<div>${esc(t.title)}<small>${short(t.date)} · ${t.start}–${t.end}</small></div>${textBtn('Edit','task',`data-id="${t.id}"`)}</div>`;}).join('')}${auto.activatedAt?`<div class="form-actions">${auto.operationalAt?badge('Operational · '+short(auto.operationalAt)):btn('Mark operational after handover','operational','quiet small')}${btn('Add optional maintenance','maintenance','quiet small')}</div>`:''}${auto.operationalAt?'<p class="subtitle">Operational. Sprint stages are removed from the future timetable. Maintenance is optional and added only when needed.</p>':''}</section>
<section class="panel"><h2>Urgent admin · Maven</h2><p>Your actual assessment expiry is unconfirmed. Check the invitation received 29 September. Your brother’s 9 November deadline is not yours.</p><form data-form="maven">${select('Assessment status','maven-status',[['pending','Verify / still outstanding'],['done','Completed'],['unavailable','Inaccessible or expired · resolved']],state.mavenResolved?'done':'pending')}<div class="form-actions"><button class="button small">Save status</button></div></form>${textBtn('Enter confirmed expiry','deadline','data-id="maven"')}<hr class="rule"><h3>Driving test</h3><p>Existing booking: 11 December. Reschedule to a suitable replacement, then enter its actual date.</p>${textBtn('Update driving test date','deadline','data-id="driving"')}</section>
<section class="panel span-2"><h2>Your everyday defaults</h2><form data-form="preferences"><div class="form-row">${select('Appearance','pref-theme',[['dark','Calm dark'],['light','Soft light'],['system','Follow device']],prefs.theme)}${select('Campus journey each way','pref-travel',[15,20,25,30,40,45,60].map(x=>[x,x+' minutes']),prefs.travelMinutes)}</div>${checkLabel('Suggest optional Greggs / outside breakfast on Monday, Wednesday and Friday','pref-greggs',prefs.greggs)}<div class="form-row">${field('11 Nov lab arrival (09:00–10:45)','pref-arrival','time',prefs.labArrival,'min="09:00" max="10:45" required')}<p>Lab window stays 09:00–11:00. Later arrival is subject to staff permission. Travel and morning routine adjust around your arrival.</p></div><div class="form-actions"><button class="button small">Save preferences</button></div></form></section></div>`;}
function nextSaturday(){const d=ukNow().date;return addDays(d,(5-weekday(d)+7)%7||7);}
function render(){taskMap=new Map();progressCache=null;applyTheme();$('#nav').innerHTML=[['today','Today'],['week','Week'],['roadmap','Roadmap'],['settings','Settings']].map(([k,l])=>`<button class="nav-item ${route===k?'active':''}" data-action="nav" data-view="${k}" ${route===k?'aria-current="page"':''}>${icon(k)}<span>${l}</span></button>`).join('');$('#main').innerHTML=route==='week'?weekView():route==='roadmap'?roadmapView():route==='settings'?settingsView():todayView();updateConnection();if(route==='settings')offlineDetails();document.title=(route==='today'?'Today':route==='week'?'Your week':route==='roadmap'?'Roadmap':'Settings')+' · My Plan';}
function showTask(id){const t=taskMap.get(id);if(!t)return;const mod=PLAN.modules[moduleFor(t.subject)],notes=state.notes[id]||'',done=state.records[id]?.status==='done';modal(esc(t.title),`<div class="pill-row"><span class="pill">${short(t.date)} · ${t.start}–${t.end}</span><span class="pill">${esc(t.location||'Home')}</span>${t.optional?badge('Optional'):''}</div><p>${esc(t.detail)}</p>${t.plannedObjective?`<div class="notice green"><strong>Originally planned for this block:</strong> ${esc(t.plannedObjective.title)}. This objective is retained when you log this session; it can be queued after the unfinished checkpoint.</div>`:''}${dependencyHint(t)}${t.success?`<div class="dialog-section"><h3>A good finish looks like</h3><div class="task-outcome">${esc(t.success)}</div></div>`:''}${t.blocked?'<div class="notice">Verify ethics approval on DCS, then record it in Settings before practical work.</div>':''}${t.assessment?`<div class="dialog-section">${textBtn('View deadline + deliverables','deadline',`data-id="${t.assessment}"`)}</div>`:''}${mod?`<details class="settings-detail"><summary>Assessment guidance + permitted AI use</summary><div class="notice">${esc(mod.rule)}</div><a href="${mod.link}" target="_blank" rel="noopener noreferrer" class="muted-link">Open official NOW brief ↗</a></details>`:''}<form data-form="task-edit" data-id="${esc(id)}">${area('Session notes','task-notes',notes,'maxlength="12000" placeholder="What you did, what is blocked, the next step…"')}<details class="settings-detail"><summary>Adjust this session</summary>${field('Session title','task-title','text',t.title,'required maxlength="500"')}<div class="form-row">${field('Date','task-date','date',t.date,'required')}${field('Location','task-location','text',t.location||'Home','maxlength="200"')}</div><div class="form-row">${field('Start','task-start','time',t.start,'required')}${field('Finish','task-end','time',t.end,'required')}</div>${checkLabel('Optional extra · excluded from required daily progress','task-optional',t.optional)}</details>${formError()}<div class="form-actions"><button class="button" type="submit">Save notes / changes</button>${t.actionable?btn(done?'Undo completion':'Mark complete','modal-complete','quiet',`data-id="${esc(id)}"`):''}${t.actionable?btn('Made progress · needs more time','unfinished','quiet',`data-id="${esc(id)}"`):''}${t.actionable?btn('Defer','defer','quiet',`data-id="${esc(id)}"`):''}${btn('Find a buffer','buffer','quiet',`data-id="${esc(id)}"`)}</div></form>`,esc(LABELS[t.subject]||'PERSONAL SESSION'));}
function dependencyHint(t){if(t.continuation)return '';const pending=earlierMilestones(state,t.date,t.subject);if(!pending.length)return '';const m=pending[0];return `<details class="settings-detail"><summary>Check an earlier milestone before moving on</summary><p class="subtitle">Week ${m.week}: ${esc(m.title)}</p><p class="subtitle">If this is already done, update its milestone. If it is still needed, log the unfinished checkpoint instead of starting a dependent step.</p>${textBtn('Review the earlier week','open-week',`data-date="${m.date}"`)}</details>`;}
function showUnfinished(id){const t=taskMap.get(id);if(!t)return;const next=nextProjectSession(state,t);modal('Useful progress. A clear next step.',`<p>Record what you achieved. This ticks off the work session, while the unfinished checkpoint remains in your weekly progress until it is actually reached.</p><form data-form="unfinished" data-id="${esc(id)}">${area('What did you achieve in this session?','worked-on','','required maxlength="4000"')}${area('Exact next step','next-action',state.checkpoints?.[t.checkpointId]?.nextAction||'','required maxlength="4000" placeholder="Fix the timeout path, then repeat the recognition request test."')}${field('Estimated remaining minutes (editable later)','remaining-minutes','number',state.checkpoints?.[t.checkpointId]?.remainingMinutes||60,'required min="15" max="2400" step="15"')}${checkLabel('Continue this checkpoint in future blocks for the same module','continue-next',true)}<div class="notice green">${next?`Next suitable planned block: ${short(next.date)}, ${next.start}–${next.end}. It will show this unfinished checkpoint first; its original objective stays visible and can be queued.`:'No suitable future block was found in the next 35 days. The checkpoint stays visible; choose extra capacity or revise the plan explicitly.'} Submission checks, appointments and free evenings remain protected.</div>${formError()}${formButtons('Save progress + next step')}</form>`,'SESSION FINISHED · CHECKPOINT STILL OPEN');}
function showCheckpointFinish(id,task=null){const c=state.checkpoints?.[id];if(!c)return;modal('Confirm the checkpoint is reached.',`<p><strong>${esc(c.title)}</strong></p><p>${esc(c.nextAction)}</p><form data-form="checkpoint-finish" data-id="${esc(id)}" ${task?`data-task="${esc(task.id)}"`:''}>${field('Checkpoint completed on','checkpoint-date','date',task?.date||selectedDate,'required')}${task?.plannedObjective?checkLabel('I also completed the originally planned objective: '+esc(task.plannedObjective.title),'also-planned',false):''}<p class="subtitle">Any original objective still waiting is retained and becomes the next checkpoint. Weekly milestones are checked separately when their full outcome is reached.</p>${formError()}${formButtons('Checkpoint finished')}</form>`,'ACTUAL OUTCOME');}
function showCheckpointEdit(id){const c=state.checkpoints?.[id];if(!c)return;modal(esc(c.title),`<form data-form="checkpoint-edit" data-id="${esc(id)}">${area('Exact next step','next-action',c.nextAction,'required maxlength="4000"')}${field('Estimated remaining minutes','remaining-minutes','number',c.remainingMinutes,'required min="15" max="2400" step="15"')}${checkLabel('Continue this checkpoint in future blocks for the same module','continue-next',c.autoContinue)}${formError()}${formButtons('Save next step')}</form>`,'ADJUST THE WORK, KEEP THE PROGRESS');}
function showDeadlines(){modal('Dates that matter.',`<p>Published dates are labelled confirmed. Unknown dates stay TBC. Mark an assessment complete to release its future preparation time.</p>${deadlineItems(deadlines(state))}<div class="form-actions">${btn(icon('plus')+' Add personal deadline','new-deadline')}</div>`,'DEADLINES + ASSESSMENTS');}
function showDeadline(id){const d=deadlines(state).find(d=>d.id===id);if(!d){toast('No linked deadline for this session.');return;}const event=state.events.find(e=>e.deadlineId===id);modal(esc(d.title),`<p>${esc(d.notes)}</p><p>${d.date?short(d.date)+' '+d.date.slice(0,4)+(d.time?' · '+d.time+' UK':' · time not published'):esc(d.window||'Exact date not yet confirmed')}</p><form data-form="deadline-edit" data-id="${id}"><div class="form-row">${field('Confirmed date (leave blank if unknown)','deadline-date','date',d.date||'')}${field('Confirmed time (if published)','deadline-time','time',d.time||'')}</div>${checkLabel('This date has been confirmed from the official source / my booking','deadline-confirmed',d.status==='confirmed')}${area('Deadline notes','deadline-notes',d.notes,'maxlength="4000"')}${checkLabel('Assessment / task submitted or completed','deadline-complete',d.complete)}${field('Completed on (sets when future slots are released)','deadline-done-date','date',typeof state.assessments[id]==='string'?state.assessments[id]:selectedDate,'required')}${['cloud-exam','ai-exam','cloud-viva','fyp-viva','cog-demo','driving'].includes(id)?`<hr class="rule">${checkLabel('Add/update this as a fixed appointment once date and time are confirmed','deadline-appointment',!!event)}${field('Appointment duration (minutes)','deadline-duration','number',event?minutes(event.end)-minutes(event.start):id.includes('exam')?120:30,'min="15" max="480" step="5"')}${field('Venue / location','deadline-location','text',event?.location||'NTU · confirm room','maxlength="300"')}`:''}${formError()}${formButtons('Save date + status')}</form>`,'CONFIRMED DATES STAY DISTINCT FROM TARGETS');}
function showNewDeadline(){modal('A personal deadline.',`<form data-form="new-deadline">${field('What is due?','new-deadline-title','text','','required maxlength="250"')}${field('Date','new-deadline-date','date',selectedDate,'required')}${field('Time (optional)','new-deadline-time','time','')}${area('Deliverables / notes','new-deadline-notes','','maxlength="3000"')}${formError()}${formButtons('Add deadline')}</form>`);}
function showEvent(id=null,maintenance=false){const e=id?state.events.find(x=>x.id===id):null;const def=maintenance?{title:'Automation · optional maintenance',optional:true,subject:'auto'}:{};const x=e||def;modal(e?'Adjust your session.':maintenance?'Fix it when it needs fixing.':'Make room for something.',`<form data-form="event" data-id="${esc(e?.id||'')}">${field('Title','event-title','text',x.title||'','required maxlength="250" placeholder="Driving lesson, supervisor meeting…"')}${select('Kind of session','event-type',[['appointment','Fixed appointment / attendance'],['work','Personal work task'],['lifestyle','Personal time · no completion check']],x.type||'appointment')}${select('Belongs to','event-subject',Object.entries(LABELS).filter(([k])=>!['life','free','buffer'].includes(k)),x.subject||'admin')}${field('Date','event-date','date',x.date||selectedDate,'required')}<div class="form-row">${field('Start','event-start','time',x.start||(maintenance?'18:00':'10:00'),'required')}${field('Finish','event-end','time',x.end||(maintenance?'19:00':'11:00'),'required')}</div>${field('Location (optional)','event-location','text',x.location||'','maxlength="300"')}${area('Notes / what a good finish looks like','event-detail',x.detail||'','maxlength="5000"')}${checkLabel('Optional extra · does not count towards compulsory progress','event-optional',x.optional)}<div id="event-preview" class="notice" hidden></div>${formError()}${formButtons(e?'Save appointment':'Add session')}${e?textBtn('Delete this custom appointment','delete-event',`data-id="${esc(e.id)}"`):''}</form>`,maintenance?'OPTIONAL MAINTENANCE':'YOUR TIME');}
function showBuffer(id){const task=taskMap.get(id);if(!task)return;const slot=findBuffer(task,state,selectedDate>=task.date?selectedDate:task.date);if(!slot){modal('Choose a time that works.',`<p>No free daytime buffer was found in the next three weeks. Edit the session directly, shorten it, or add optional time if you choose.</p>${btn('Edit session','task','',`data-id="${esc(id)}"`)}`);return;}modal('A little space, found.',`<p>Move <strong>${esc(task.title)}</strong> to <strong>${long(slot.date)}, ${slot.start}–${slot.end}</strong>?</p><p>The original session will move with its notes and completion history. Nothing is duplicated.</p><div class="form-actions">${btn('Move to this buffer','apply-buffer','',`data-id="${esc(id)}" data-date="${slot.date}" data-start="${slot.start}" data-end="${slot.end}"`)}${btn('Choose another time','task','quiet',`data-id="${esc(id)}"`)}</div>`,'RESCHEDULE');}
function download(data,name){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function updateConnection(){const el=$('#connection');el.classList.toggle('offline',!navigator.onLine);el.textContent=!navigator.onLine?'Offline':registration?.active?'Offline ready':'On this device';}
async function offlineDetails(){const el=$('#offline-detail');if(!el)return;let cached=false;try{const ks=await caches.keys();cached=ks.some(k=>k.startsWith('my-plan-'));}catch{}el.textContent=cached?'App files are cached on this device. Offline navigation is ready.':'Open on HTTPS and allow the first load to finish before relying on offline mode.';}
function formData(form){return Object.fromEntries(new FormData(form).entries());}
const uid=prefix=>prefix+'/'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2));
function eventPreview(){const form=$('form[data-form=event]');if(!form)return;const f=formData(form);if(!validDate(f['event-date'])||!validTime(f['event-start'])||!validTime(f['event-end']))return;const t={start:f['event-start'],end:f['event-end']},hits=dayPlan(f['event-date'],state).tasks.filter(t2=>t2.actionable&&t2.id!==form.dataset.id&&overlap(t,t2));const p=$('#event-preview');p.hidden=!hits.length;p.textContent=hits.length?`This overlaps ${hits.map(t=>t.title).join('; ')}. The overlapping planned work will be shown under “sessions to review” so you can choose a new time.`:'';}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 try{
 if(a==='nav')setRoute(el.dataset.view);
 if(a==='date')setRoute('today',el.dataset.date);
 if(a==='open-week'){closeModal();setRoute('week',el.dataset.date);}
 if(a==='week')setRoute('week');
 if(a==='prev-date'||a==='next-date')setRoute(route,addDays(selectedDate,(a==='prev-date'?-1:1)*Number(el.dataset.step||1)));
 if(a==='close')closeModal();
 if(a==='task')showTask(id);
 if(a==='unfinished')showUnfinished(id);
 if(a==='resolve-checkpoint')showCheckpointFinish(id);
 if(a==='edit-checkpoint')showCheckpointEdit(id);
 if(a==='enable-checkpoint'){state.checkpoints[id].autoContinue=true;save();render();toast('Future module blocks will pick up this checkpoint.');}
 if(a==='check-task'||a==='modal-complete'){const t=taskMap.get(id);if(!t)return;const done=state.records[id]?.status==='done';if(!done&&t.checkpointId){showCheckpointFinish(t.checkpointId,t);return;}finishSession(state,t,!done);save();if(a==='modal-complete')closeModal();render();toast(done?'Completion undone.':'A good step forward.');}
 if(a==='check-milestone'){state.milestones[id]=!state.milestones[id];save();render();}
 if(a==='deadline')showDeadline(id);
 if(a==='deadlines')showDeadlines();
 if(a==='new-deadline')showNewDeadline();
 if(a==='new-event')showEvent();
 if(a==='edit-event')showEvent(id);
 if(a==='maintenance')showEvent(null,true);
 if(a==='delete-event'){modal('Remove this appointment?',`<p>The custom appointment will be removed and any displaced planned work can return to its original time.</p><div class="form-actions">${btn('Remove appointment','confirm-delete-event','danger',`data-id="${esc(id)}"`)}${btn('Keep it','close','quiet')}</div>`);}
 if(a==='confirm-delete-event'){state.events=state.events.filter(e=>e.id!==id);delete state.records[id];save();closeModal();render();toast('Appointment removed.');}
 if(a==='defer'){const t=taskMap.get(id);deferTask(state,t);save();closeModal();render();toast('Deferred. Choose a new time when useful.');}
 if(a==='buffer')showBuffer(id);
 if(a==='apply-buffer'){moveTask(state,taskMap.get(id),{date:el.dataset.date,start:el.dataset.start,end:el.dataset.end});save();closeModal();setRoute('today',el.dataset.date);toast('Session moved. Notes stay with it.');}
 if(a==='export'){state.lastBackup=new Date().toISOString();save();download(backup(state),'my-plan-backup-'+ukNow().date+'.json');toast('Backup downloaded. Keep it somewhere safe.');if(route==='settings')render();}
 if(a==='export-raw'){download(localStorage.getItem(KEY)||'{}','my-plan-raw-recovery.json');}
 if(a==='import')$('#import-file').click();
 if(a==='restore-replace'||a==='restore-merge'){if(!pendingImport)return;state=a==='restore-replace'?pendingImport:mergeStates(state,pendingImport);pendingImport=null;save();closeModal();render();toast('Backup restored on this device.');}
 if(a==='operational'){
  if(!state.automation.tasks.every(t=>state.records[t.id]?.status==='done')){toast('Complete and validate each sprint stage before handover.');return;}
  state.automation.operationalAt=ukNow().date;save();render();toast('Operational. Future sprint slots released.');
 }
 if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;render();}else toast('In Android Chrome: ⋮ → Install app / Add to Home screen.');}
 if(a==='check-update'){if(registration){await registration.update();toast(registration.waiting?'An update is ready above.':'Checked for the latest app files.');}else toast('Install/update checks need an HTTPS-hosted app.');}
 if(a==='persist-storage'){const yes=await navigator.storage?.persist?.();toast(yes?'Durable storage granted. Keep backups too.':'Storage protection was not granted; continue keeping JSON backups.');}
 }catch(e){const error=$('#dialog-error');if(error)error.textContent=e.message;else toast(e.message);}
});
document.addEventListener('change',e=>{if(e.target.id==='date-picker')setRoute(route,e.target.value);if(e.target.dataset.ucl!==undefined){state.uclChecklist[e.target.dataset.ucl]=e.target.checked;save();}if(e.target.dataset.lab){state.labTasks[e.target.dataset.lab]=e.target.checked;save();}if(e.target.closest('form[data-form=event]'))eventPreview();});
document.addEventListener('input',e=>{if(e.target.closest('form[data-form=event]'))eventPreview();});
document.addEventListener('submit',async ev=>{const form=ev.target.closest('[data-form]');if(!form)return;ev.preventDefault();const f=formData(form),kind=form.dataset.form,previous=structuredClone(state);let close=true;
 try{
 if(kind==='unfinished'){
  const t=taskMap.get(form.dataset.id);logUnfinished(state,t,{progressNote:f['worked-on'],nextAction:f['next-action'],remainingMinutes:Number(f['remaining-minutes']),continueNext:!!f['continue-next']});
 }
 if(kind==='checkpoint-finish'){
  const t=form.dataset.task?taskMap.get(form.dataset.task):null;resolveCheckpoint(state,form.dataset.id,f['checkpoint-date'],t,!!f['also-planned']);
 }
 if(kind==='checkpoint-edit'){
  const c=state.checkpoints[form.dataset.id],estimate=Number(f['remaining-minutes']);if(!f['next-action']?.trim()||estimate<15||estimate>2400)throw Error('Add a concrete next step and a 15–2400 minute estimate.');Object.assign(c,{nextAction:f['next-action'].trim(),remainingMinutes:estimate,autoContinue:!!f['continue-next'],updatedAt:new Date().toISOString()});
 }
 if(kind==='day-note'){state.notes[selectedDate]=f['day-note'];close=false;}
 if(kind==='task-edit'){
  const id=form.dataset.id,t=taskMap.get(id);const edit={title:f['task-title'],date:f['task-date'],start:f['task-start'],end:f['task-end'],location:f['task-location'],optional:!!f['task-optional']};
  if(edit.title!==t.title||edit.date!==t.date||edit.start!==t.start||edit.end!==t.end||edit.location!==(t.location||'Home')||edit.optional!==!!t.optional)moveTask(state,t,edit);
  state.notes[id]=f['task-notes'];
  if(id.startsWith('automation/')){const stage=state.automation.tasks.find(x=>x.id===id);Object.assign(stage,edit);delete state.overrides[id];}
  if(t.user&&state.events.some(x=>x.id===id)){Object.assign(state.events.find(x=>x.id===id),edit,{originDate:state.overrides[id]?.originDate||t.originDate||t.date});delete state.overrides[id];}
 }
 if(kind==='deadline-edit'){
  const id=form.dataset.id,date=f['deadline-date'],time=f['deadline-time'];if(date&&!validDate(date))throw Error('Enter a valid date.');if(time&&!date)throw Error('Enter a date before a time.');if((date||time)&&!f['deadline-confirmed'])throw Error('Confirm the entered date from its source, or leave it blank.');
  state.deadlineEdits[id]={date:date||null,time:time||null,status:date?'confirmed':'tbc',notes:f['deadline-notes']};
  if(f['deadline-complete'])state.assessments[id]=f['deadline-done-date'];else delete state.assessments[id];
  if(id==='ucl')state.uclSubmittedAt=f['deadline-complete']?f['deadline-done-date']:'';
  if(id==='maven')state.mavenResolved=f['deadline-complete']?f['deadline-done-date']:'';
  if(f['deadline-appointment']){
   if(!date||!time)throw Error('A confirmed appointment needs its actual date and start time.');const duration=Number(f['deadline-duration']);if(minutes(time)+duration>1439)throw Error('Appointment must finish on the same date.');const existing=state.events.find(e=>e.deadlineId===id);const d=deadlines(state).find(d=>d.id===id);const e={id:existing?.id||uid('appointment'),deadlineId:id,title:d.title,date,start:time,end:timeStr(minutes(time)+duration),subject:d.category,category:moduleFor(d.category),location:f['deadline-location'],detail:d.notes,optional:false,type:'appointment'};state.events=state.events.filter(e=>e.deadlineId!==id).concat(e);
  } else state.events=state.events.filter(e=>e.deadlineId!==id);
 }
 if(kind==='new-deadline')state.customDeadlines.push({id:uid('deadline'),title:f['new-deadline-title'],date:f['new-deadline-date'],time:f['new-deadline-time']||null,notes:f['new-deadline-notes'],category:'admin',status:'confirmed'});
 if(kind==='event'){
  const date=f['event-date'],start=f['event-start'],end=f['event-end'];if(!validDate(date)||!validTime(start)||!validTime(end)||start>=end)throw Error('Choose a date and finish time after the start.');const id=form.dataset.id||uid('event'),subject=f['event-subject'];const previousEvent=state.events.find(x=>x.id===id);const e={id,originDate:previousEvent?.originDate||previousEvent?.date||date,title:f['event-title'].trim(),date,start,end,subject,category:moduleFor(subject),type:f['event-type'],optional:!!f['event-optional'],location:f['event-location']||'Your choice',detail:f['event-detail'],success:f['event-detail']||'Attend or complete the planned action.'};
  if(!e.title)throw Error('Give the session a title.');state.events=state.events.filter(e=>e.id!==id).concat(e);selectedDate=date;
 }
 if(kind==='business'){for(const k of Object.keys(state.business)){const v=f[k];if(v!==''&&(!Number.isFinite(Number(v))||Number(v)<0))throw Error('Use nonnegative figures or leave unknown metrics blank.');state.business[k]=v;}close=false;}
 if(kind==='quant'){if(Number(f.solved)>Number(f.attempted))throw Error('Solved cannot be greater than attempted.');state.quantLog.push({id:uid('practice'),date:f['practice-date'],topic:f['quant-topic'],attempted:Number(f.attempted),solved:Number(f.solved),timed:Number(f.timed),mistake:f.mistake});close=false;}
 if(kind==='ucl'){state.uclTarget=f['ucl-target'];state.uclSubmittedAt=f['ucl-submitted'];if(state.uclSubmittedAt)state.assessments.ucl=state.uclSubmittedAt;else delete state.assessments.ucl;close=false;}
 if(kind==='ethics'){state.ethics={approved:!!f['ethics-approved'],date:f['ethics-date'],reference:f['ethics-reference']};close=false;}
 if(kind==='maven'){state.mavenResolved=f['maven-status']==='pending'?'':ukNow().date;if(state.mavenResolved)state.assessments.maven=state.mavenResolved;else delete state.assessments.maven;close=false;}
 if(kind==='automation'){
  const a=state.automation;if(!f['auto-agreed']||!f['auto-documents'])throw Error('Confirm agreement and receive the workflow documents before activating the sprint.');
  const start=f['auto-start'],hours=Number(f['auto-hours']);if(!validDate(start)||hours<2||hours>40)throw Error('Choose a valid start and a 2–40 hour estimate.');
  if(!a.activatedAt){a.tasks=automationTasks(start,hours);a.activatedAt=ukNow().date;}Object.assign(a,{confirmed:true,documents:true,start,hours});close=false;
 }
 if(kind==='preferences'){state.preferences={...state.preferences,theme:f['pref-theme'],greggs:!!f['pref-greggs'],travelMinutes:Number(f['pref-travel']),labArrival:f['pref-arrival']};close=false;}
 save();if(close)closeModal();render();if(!close&&['business','quant'].includes(kind)){const savedForm=$('form[data-form='+kind+']');if(savedForm)savedForm.closest('details').open=true;}toast(kind==='event'?'Session added. Review any displaced work below.':'Saved on this device.');
 }catch(e){state=previous;const err=$('#dialog-error');if(err)err.textContent=e.message;else toast(e.message);}
});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{const result=parseBackup(await file.text());pendingImport=result.state;modal('Restore your planner.',`<p>${esc(result.report)}</p><p>This backup has ${Object.keys(result.state.records).length} session records and ${result.state.events.length} appointments. Export your current state first if you want to keep a separate copy.</p><p><strong>Replace</strong> uses the entire backup, including preferences and project status. <strong>Merge</strong> adds records, appointments and notes; the latest completion timestamp wins. Current project statuses and preferences stay in place.</p><div class="form-actions">${btn('Merge with this device','restore-merge','')}${btn('Replace this device’s data','restore-replace','quiet')}${btn('Cancel','close','quiet')}</div>`,'VALIDATED JSON BACKUP');}catch(err){toast(err.message);}});
$('#jump-today').addEventListener('click',()=>setRoute('today',ukNow().date));
$('#theme-toggle').addEventListener('click',()=>{state.preferences.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';save();applyTheme();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{readRoute();render();window.scrollTo({top:0});});
window.addEventListener('online',updateConnection);window.addEventListener('offline',updateConnection);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;if(route==='settings')render();});
window.addEventListener('storage',e=>{if(e.key===KEY){try{state=loadState().state;render();toast('Progress updated from another tab.');}catch{}}});
setInterval(()=>{const now=ukNow();const stamp=now.date+now.time;if(stamp!==lastMinute){lastMinute=stamp;if(route==='today'&&followingToday&&selectedDate!==now.date&&!$('#modal').open&&!document.activeElement?.matches('input,textarea,select')){setRoute('today',now.date);return;}if(route==='today'&&selectedDate===now.date&&!$('#modal').open&&!document.activeElement?.matches('input,textarea,select'))render();}},15000);
if('serviceWorker' in navigator&&location.protocol!=='file:'){
 navigator.serviceWorker.register('./service-worker.js',{scope:'./',updateViaCache:'none'}).then(r=>{registration=r;updateConnection();const show=()=>{if(r.waiting&&navigator.serviceWorker.controller)$('#update-banner').hidden=false;};show();r.addEventListener('updatefound',()=>{const worker=r.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'){show();updateConnection();if(route==='settings')offlineDetails();}});});}).catch(()=>{const e=$('#connection');e.textContent='Offline setup unavailable';});
 let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing)return;refreshing=true;location.reload();});
 $('#apply-update').addEventListener('click',()=>{if(!save())return;registration?.waiting?.postMessage({type:'SKIP_WAITING'});});
}
readRoute();render();if(loadWarning){$('#storage-error').textContent=loadWarning;$('#storage-error').hidden=false;}
